"""Brightwell procedure code reference: BWP codes -> specialty, description, payer, slot length, band.

Generated from the clinical coding workbook (coding team) and maintained by hand since 2024.
One row per (procedure, variant, payer). Payer NHSC = NHS-commissioned, HSEC = HSE-commissioned (IE).
Bands price in GBP; see BAND_PRICE_GBP. Lookups: lookup(code, payer).
"""
from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class ProcedureCode:
    code: str
    specialty: str
    description: str
    payer: str
    minutes: int
    band: str


