_INDEX: dict[tuple[str, str], ProcedureCode] = {}
for _r in _ROWS:
    _pc = ProcedureCode(*_r)
    _INDEX[(_pc.code, _pc.payer)] = _pc


def lookup(code: str, payer: str = "SELF") -> ProcedureCode:
    code = LEGACY_REMAP.get(code, code)
    try:
        return _INDEX[(code, payer)]
    except KeyError:
        for (c, _p), pc in _INDEX.items():
            if c == code:
                return pc
        raise KeyError(f"unknown procedure code {code}")


def codes_for(specialty: str) -> list[str]:
    return sorted({pc.code for pc in _INDEX.values() if pc.specialty == specialty})
